import{_ as t,o as a,c as o,a5 as i}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"Choice","description":"","frontmatter":{"title":"Choice","order":7},"headers":[],"relativePath":"en/2.4/tutorial/script/choice.md","filePath":"en/2.4/tutorial/script/choice.md","lastUpdated":1788455378000}'),n={name:"en/2.4/tutorial/script/choice.md"};function s(c,e,r,h,d,l){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="choice-jump" tabindex="-1">Choice Jump <a class="header-anchor" href="#choice-jump" aria-label="Permalink to &quot;Choice Jump&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This feature must be used together with the <strong>branch feature</strong>. Its core purpose is to configure jump logic inside interactive option tags. After the player clicks the corresponding option, the script can jump directly to the specified branch node. Each <code>choice</code> statement creates one option. Multiple adjacent <code>choice</code> lines are merged into one option group and shown together during interaction.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;option text&quot; -&gt; branch_name</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>Option text</td><td>Yes</td><td>&quot;Choose coffee&quot;</td><td>Option text shown during interaction</td></tr><tr><td>Branch name</td><td>Yes</td><td>coffee_choice</td><td>Unique identifier of the target branch</td></tr></tbody></table><h2 id="usage-examples" tabindex="-1">Usage Examples <a class="header-anchor" href="#usage-examples" aria-label="Permalink to &quot;Usage Examples&quot;">​</a></h2><p>Each option can be written on its own line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;Green tea&quot; -&gt; green_tea</span></span>
<span class="line"><span>choice &quot;Black tea&quot; -&gt; black_tea</span></span></code></pre></div><p>Multiple options can also be written continuously on one line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;Green tea&quot; -&gt; green_tea &quot;Black tea&quot; -&gt; black_tea</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ol><li>The branch name must exactly match the branch identifier defined in the project. It is case-sensitive and cannot contain spaces or special symbols.</li><li>Option text must be wrapped in English double quotes and supports regular text characters.</li><li><code>-&gt;</code> is the separator between the option and the branch name and cannot be omitted.</li></ol>`,13)])])}const b=t(n,[["render",s]]);export{u as __pageData,b as default};
